sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
  if (newValue === '') {
    return;
  }

  var ga = new GlideAjax('SigaUtils');
  ga.addParam('sysparm_name', 'getBulletInfo');
  ga.addParam('sysparm_bullet', newValue);

  ga.getXML(function(response) {
    var answer = response.responseXML.documentElement.getAttribute('answer');
    if (answer) {
      var data = JSON.parse(answer);
    //   g_form.addInfoMessage(answer);
      // Set values to the form
      g_form.setValue('alavancaref', data.alavanca);
      g_form.setValue('dimensao', data.dimensao);
      g_form.setValue('dominio', data.dominio);
    } else {
      g_form.clearValue('alavancaref');
      g_form.clearValue('dimensao');
      g_form.clearValue('dominio');
    }
  });
}

